@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class CentrifugeProbe{
 public static final BlockPos P=new BlockPos(2080,205,8);public static volatile boolean ready;static int ticks,stage;static long due;static ServerPlayer actor;static CentrifugeEntity live;static AlchemyMachine source,sink;static boolean inspected;
 public static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static CentrifugeEntity centrifuge(ServerLevel l,BlockPos at){l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(at,EssentiaContent.CENTRIFUGE.get().defaultBlockState());return (CentrifugeEntity)l.getBlockEntity(at);}
 static AlchemyMachine jar(ServerLevel l,BlockPos at,boolean alembic){l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(at,(alembic?AlchemyContent.ALEMBIC:AlchemyContent.JAR).get().defaultBlockState());return (AlchemyMachine)l.getBlockEntity(at);}
 static void restore(CentrifugeEntity c,CentrifugeState s){var l=c.getLevel();var tag=c.saveWithoutMetadata(l.registryAccess());tag.put("centrifuge",CentrifugeState.CODEC.encodeStart(NbtOps.INSTANCE,s).getOrThrow());c.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));c.setChanged();l.sendBlockUpdated(c.getBlockPos(),c.getBlockState(),c.getBlockState(),Block.UPDATE_CLIENTS);}
 static void recipe(ServerPlayer p){var l=p.level();var at=P.offset(-6,0,-4);l.setBlockAndUpdate(at,ArcaneContent.WORKBENCH.get().defaultBlockState());var w=(ArcaneWorkbenchEntity)l.getBlockEntity(at);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(at));KnowledgeStore.write(p,KnowledgeState.EMPTY);w.inventory.setItem(1,new ItemStack(EssentiaContent.TUBES.get("tube").get()));w.inventory.setItem(3,new ItemStack(SimpleContent.ITEMS.get("morphic_resonator").get()));w.inventory.setItem(4,new ItemStack(SimpleContent.ITEMS.get("metal_alchemical").get()));w.inventory.setItem(5,new ItemStack(SimpleContent.ITEMS.get("mechanism_simple").get()));w.inventory.setItem(7,new ItemStack(EssentiaContent.TUBES.get("tube").get()));w.inventory.setItem(13,CrystalContent.essence("ordo",1));w.inventory.setItem(14,CrystalContent.essence("perditio",1));for(var a:w.sources())AuraData.get(l).put(AuraCell.key(a.getX()>>4,a.getZ()>>4),new AuraCell(500,500,0));var match=w.match();check(match!=null&&match.vis()==100&&match.result().is(EssentiaContent.CENTRIFUGE_ITEM.get()),"Centrifuge recipe missing");int vis=w.availableVis();check(!w.craft(p)&&w.availableVis()==vis&&w.inventory.getItem(15).isEmpty(),"Research lock bypassed");KnowledgeStore.write(p,ResearchService.state(p).stage("TUBES",999).stage("CENTRIFUGE",1).addPoints("THEORY","ALCHEMY",32));check(ResearchService.advance(p,"CENTRIFUGE")&&ResearchService.knows(p,"CENTRIFUGE")&&ResearchService.state(p).raw("THEORY","ALCHEMY")==0,"Centrifuge research unavailable");check(w.craft(p)&&vis-w.availableVis()==100&&w.inventory.getItem(15).is(EssentiaContent.CENTRIFUGE_ITEM.get()),"Arcane centrifuge payment failed");for(int i=0;i<15;i++)check(w.inventory.getItem(i).isEmpty(),"Arcane payment slot "+i);check(ResearchService.state(p).crafts().contains("thaumcraft:centrifuge"),"Craft proof missing");Thaumcraft.LOGGER.info("CENTRIFUGE_RECIPE_OK: actual research, locked refusal, 100 vis and exact crystals/ingredients");}
 static void mechanics(ServerLevel l){var c=centrifuge(l,P);for(var d:Direction.values())check(c.connects(d)==(d.getAxis()==Direction.Axis.Y),"Invalid connection "+d);check(c.suction(Direction.DOWN)==128&&c.suction(Direction.UP)==0,"Idle suction wrong");for(var a:List.of("aer","terra","ignis","aqua","ordo","perditio","bogus"))check(!c.insert(a,Direction.DOWN,false),"Accepted primal/unknown "+a);check(!c.insert("potentia",Direction.NORTH,false)&&!c.extract("ignis",Direction.DOWN,false),"Wrong face accepted");check(c.insert("potentia",Direction.DOWN,true)&&c.snapshot().equals(CentrifugeState.EMPTY),"Simulation mutated input");check(c.insert("potentia",Direction.DOWN,false)&&c.suction(Direction.DOWN)==64&&!c.insert("lux",Direction.DOWN,false),"Input capacity wrong");for(int i=0;i<10;i++)c.serverTick();int remain=c.snapshot().remaining();l.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());for(int i=0;i<70;i++)c.serverTick();check(c.snapshot().remaining()==remain&&c.suction(Direction.DOWN)==0&&!c.getBlockState().getValue(CentrifugeBlock.ACTIVE),"Powered machine progressed");l.removeBlock(P.east(),false);for(int i=0;i<remain;i++)c.serverTick();var out=c.snapshot().output();check(AspectCatalog.components("potentia").contains(out)&&c.snapshot().input().isEmpty(),"Wrong separator output");check(c.extract(out,Direction.UP,true)&&c.snapshot().output().equals(out),"Output simulation mutated");check(c.insert("lux",Direction.DOWN,false),"Pending input capacity unavailable");for(int i=0;i<60;i++)c.serverTick();check(c.snapshot().input().equals("lux")&&c.snapshot().output().equals(out)&&c.snapshot().remaining()==0,"Output overwritten");l.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(c.extract(out,Direction.UP,false)&&!c.extract(out,Direction.UP,false),"Extraction duplicated or blocked by power");check(!c.insert("lux",Direction.DOWN,false),"Powered insertion accepted");l.removeBlock(P.east(),false);c.serverTick();check(c.snapshot().input().isEmpty()&&AspectCatalog.components("lux").contains(c.snapshot().output()),"Blocked input failed to resume");
  var raw=c.saveWithoutMetadata(l.registryAccess());var future=new CompoundTag();future.putInt("version",999);future.putString("future_payload","preserve-me");raw.put("centrifuge",future);c.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),raw));c.serverTick();check(!c.supported()&&!c.connects(Direction.UP)&&!c.insert("lux",Direction.DOWN,false)&&future.equals(c.saveWithoutMetadata(l.registryAccess()).get("centrifuge")),"Future data lost or active");
  c=centrifuge(l,P);int a=0,b=0;l.getRandom().setSeed(1931);for(int n=0;n<64;n++){check(c.insert("potentia",Direction.DOWN,false),"Batch input failed");for(int t=0;t<39;t++)c.serverTick();String v=c.snapshot().output();if(v.equals("ignis"))a++;else if(v.equals("ordo"))b++;else throw new AssertionError("Batch unknown component "+v);check(c.extract(v,Direction.UP,false)&&!c.extract(v,Direction.UP,false),"Batch output duplication");}check(a+b==64&&a>0&&b>0,"Random batch did not conserve units");Thaumcraft.LOGGER.info("CENTRIFUGE_MECHANICS_OK: 64 compounds -> {} ignis + {} ordo; faces, exact timer, power, buffers, simulations and future data",a,b);
 }
 static void pipe(ServerLevel l,BlockPos p){l.setBlockAndUpdate(p,EssentiaContent.TUBES.get("tube").get().defaultBlockState());}
 static void network(ServerLevel l){live=centrifuge(l,P);source=jar(l,P.below(2),true);check(source.insertEssence("potentia",12,false),"Feed setup failed");pipe(l,P.below());pipe(l,P.above());pipe(l,P.above().east());pipe(l,P.east());sink=jar(l,P.east().below(),false);due=l.getGameTime()+650;stage=2;}
 static void gallery(ServerLevel l){for(var p:BlockPos.betweenClosed(P.offset(-8,0,-5),P.offset(8,8,10)))l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());for(var p:BlockPos.betweenClosed(P.offset(-8,-1,-5),P.offset(8,-1,10)))l.setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());for(int i=0;i<2;i++){var at=P.offset(i*5-2,1,0);var input=jar(l,at.below(),true);input.insertEssence(i==0?"potentia":"lux",100,false);var c=centrifuge(l,at);l.setBlockAndUpdate(at.above(),EssentiaContent.TUBES.get("tube_buffer").get().defaultBlockState());for(var d:List.of(Direction.EAST,Direction.WEST)){pipe(l,at.above().relative(d));var output=jar(l,at.relative(d),false);output.insertEssence(AspectCatalog.components(i==0?"potentia":"lux").get(d==Direction.EAST?0:1),1,false);l.setBlockAndUpdate(at.relative(d).below(),Blocks.STONE.defaultBlockState());}if(i==1){restore(c,new CentrifugeState(1,"lux","",23));l.setBlockAndUpdate(at.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());}}
  actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+7.5,Set.of(),180,17,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();actor.getInventory().clearContent();actor.getInventory().setSelectedSlot(0);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(EssentiaContent.RESONATOR.get()));l.getServer().getCommands().performPrefixedCommand(l.getServer().createCommandSourceStack(),"time set day");ready=true;stage=4;Thaumcraft.LOGGER.info("CENTRIFUGE_CLIENT_OK: working and redstone-paused separators connected to physical tubes and jars");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("centrifuge-"))return;var l=e.server().overworld();boolean client=!e.server().isDedicatedServer();if(++ticks<80)return;if(stage==4)return;
  if(stage==0){if(client){if(e.server().getPlayerList().getPlayers().isEmpty())return;actor=e.server().getPlayerList().getPlayers().getFirst();if(!actor.isAlive())return;actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+7.5,Set.of(),180,4,true);}else actor=new ServerPlayer(e.server(),l,new GameProfile(UUID.fromString("83776ad5-38b3-4f73-954a-37390768fdab"),"CentrifugeProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){} @Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};for(int x=129;x<=131;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);stage=1;due=l.getGameTime()+60;return;}
  if(stage==1&&l.getGameTime()>=due){if(mode().equals("centrifuge-read")){var c=(CentrifugeEntity)l.getBlockEntity(P.offset(6,0,0));check(c!=null&&c.supported()&&c.snapshot().equals(new CentrifugeState(1,"lux","ignis",17))&&c.powered(),"Restart lost paid work or exact progress");l.removeBlock(c.getBlockPos().east(),false);check(c.extract("ignis",Direction.UP,false),"Restart output unavailable");for(int n=0;n<17;n++)c.serverTick();check(c.snapshot().input().isEmpty()&&AspectCatalog.components("lux").contains(c.snapshot().output()),"Restart work failed to resume");var old=(AlchemyMachine)l.getBlockEntity(SmelterProbe.P.offset(15,0,0));check(old!=null&&old.supported()&&old.tier()==2,"Previous port smelter lost");Thaumcraft.LOGGER.info("CENTRIFUGE_RESTART_OK: both paid buffers, exact remaining time, power, resume and actual port.30 machine");stage=4;e.server().halt(false);return;}
   for(var p:BlockPos.betweenClosed(P.offset(-8,-3,-5),P.offset(8,8,10)))l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());for(var p:BlockPos.betweenClosed(P.offset(-8,-4,-5),P.offset(8,-4,10)))l.setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());recipe(actor);mechanics(l);if(client)actor.teleportTo(l,P.getX()+.5,P.getY()+3,P.getZ()+7.5,Set.of(),180,4,true);network(l);return;}
  if(stage==2&&l.getGameTime()>=due){int left=source.total()+(live.snapshot().input().isEmpty()?0:1)+(live.snapshot().output().isEmpty()?0:1);for(var at:List.of(P.below(),P.above(),P.above().east(),P.east()))left+=((TubeEntity)l.getBlockEntity(at)).total();check(source.total()<12&&sink.total()>0&&left+sink.total()==12,"Physical tubes/jars lost or duplicated units: left="+left+" sink="+sink.total());check(sink.aspects().keySet().stream().allMatch(AspectCatalog.components("potentia")::contains),"Network wrong aspect");Thaumcraft.LOGGER.info("CENTRIFUGE_NETWORK_OK: real native world ticks, physical tubes and jar, total=12 collected={}",sink.total());if(client)gallery(l);else{var c=centrifuge(l,P.offset(6,0,0));restore(c,new CentrifugeState(1,"lux","ignis",17));l.setBlockAndUpdate(c.getBlockPos().east(),Blocks.REDSTONE_BLOCK.defaultBlockState());Thaumcraft.LOGGER.info("CENTRIFUGE_WRITE_OK: paid input and output with remaining=17 and redstone saved");stage=4;e.server().halt(false);}}
 }
}
